# 设置MAAS_BASE_URL、MAAS_API_KEY，并替换下面的真实artifact ID。
# 新操作仅生成一次并保存；同次重试沿用原键和原JSON。
IDEMPOTENCY_KEY="$(python3 -c 'import uuid; print(uuid.uuid4())')"
curl -i --request POST \
  --url "$MAAS_BASE_URL/maas/v1/tasks" \
  --header "Authorization: Bearer $MAAS_API_KEY" \
  --header 'Accept: application/json' \
  --header 'Content-Type: application/json' \
  --header "Idempotency-Key: $IDEMPOTENCY_KEY" \
  --data '{
    "model": "ocr.default",
    "input": {
      "image": {
        "artifact_id": "art_REPLACE_WITH_UPLOADED_ID"
      }
    },
    "parameters": {},
    "timeout_seconds": 120,
    "max_attempts": 1
  }'
